import os
from typing import Any, Dict, List, Optional

from google.cloud import documentai_v1 as documentai


def _text_from_layout(
    layout: documentai.Document.Page.Layout,
    full_text: str,
) -> str:
    if not layout.text_anchor.text_segments:
        return ""
    parts: List[str] = []
    for segment in layout.text_anchor.text_segments:
        start = int(segment.start_index) if segment.start_index is not None else 0
        end = int(segment.end_index) if segment.end_index is not None else 0
        parts.append(full_text[start:end])
    return "".join(parts).strip()


def _norm_poly(
    vertices: List[documentai.Document.Page.Dimension],
) -> List[Dict[str, float]]:
    return [{"x": float(v.x), "y": float(v.y)} for v in vertices]


def _layout_bbox(layout: documentai.Document.Page.Layout) -> List[Dict[str, float]]:
    poly = layout.bounding_poly
    if poly and poly.normalized_vertices:
        return [{"x": float(v.x), "y": float(v.y)} for v in poly.normalized_vertices]
    if poly and poly.vertices:
        return [{"x": float(v.x), "y": float(v.y)} for v in poly.vertices]
    return []


def extract_tables_and_rows(
    *,
    project_id: str,
    location: str,
    processor_id: str,
    file_path: str,
    mime_type: str,
    processor_version: Optional[str] = None,
) -> Dict[str, Any]:
    client = documentai.DocumentProcessorServiceClient(
        client_options={"api_endpoint": f"{location}-documentai.googleapis.com"}
    )

    with open(file_path, "rb") as f:
        raw_bytes = f.read()

    if processor_version:
        name = client.processor_version_path(
            project_id, location, processor_id, processor_version
        )
    else:
        name = client.processor_path(project_id, location, processor_id)

    request = documentai.ProcessRequest(
        name=name,
        raw_document=documentai.RawDocument(
            content=raw_bytes,
            mime_type=mime_type,
        ),
    )

    result = client.process_document(request=request)
    document = result.document

    extracted_tables: List[Dict[str, Any]] = []

    for page_index, page in enumerate(document.pages):
        page_tables: List[Dict[str, Any]] = []

        for table_index, table in enumerate(page.tables):
            header_rows: List[Dict[str, Any]] = []
            body_rows: List[Dict[str, Any]] = []

            for row_index, row in enumerate(table.header_rows):
                cells: List[Dict[str, Any]] = []
                for cell_index, cell in enumerate(row.cells):
                    cells.append(
                        {
                            "cell_index": cell_index,
                            "row_span": int(cell.row_span),
                            "col_span": int(cell.col_span),
                            "text": _text_from_layout(cell.layout, document.text),
                            "bbox": _layout_bbox(cell.layout),
                            "confidence": float(cell.layout.confidence)
                            if cell.layout.confidence is not None
                            else None,
                        }
                    )
                header_rows.append(
                    {
                        "row_index": row_index,
                        "row_type": "header",
                        "cells": cells,
                    }
                )

            for row_index, row in enumerate(table.body_rows):
                cells = []
                for cell_index, cell in enumerate(row.cells):
                    cells.append(
                        {
                            "cell_index": cell_index,
                            "row_span": int(cell.row_span),
                            "col_span": int(cell.col_span),
                            "text": _text_from_layout(cell.layout, document.text),
                            "bbox": _layout_bbox(cell.layout),
                            "confidence": float(cell.layout.confidence)
                            if cell.layout.confidence is not None
                            else None,
                        }
                    )
                body_rows.append(
                    {
                        "row_index": row_index,
                        "row_type": "body",
                        "cells": cells,
                    }
                )

            page_tables.append(
                {
                    "table_index": table_index,
                    "page": page_index + 1,
                    "bbox": _layout_bbox(table.layout),
                    "header_rows": header_rows,
                    "body_rows": body_rows,
                    "all_rows": header_rows + body_rows,
                }
            )

        extracted_tables.extend(page_tables)

    return {
        "provider": "google_cloud_document_ai",
        "api_endpoint": f"{location}-documentai.googleapis.com",
        "processor_id": processor_id,
        "processor_version": processor_version,
        "file_path": file_path,
        "mime_type": mime_type,
        "tables": extracted_tables,
    }
